import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Projects","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md","lastUpdated":1785589481000}'),n={name:"projects/index.md"};function i(s,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><h2 id="🛡️-openshield-xdp" tabindex="-1">🛡️ OpenShield-XDP <a class="header-anchor" href="#🛡️-openshield-xdp" aria-label="Permalink to &quot;🛡️ OpenShield-XDP&quot;">​</a></h2><p>XDP-native DDoS mitigation at line rate. 16-stage detection pipeline with Bloom filter whitelist acceleration and freplace hot-patching.</p><p><a href="/pingless-studios-docs/openshield-xdp/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="⚡-bandwidth-manager" tabindex="-1">⚡ Bandwidth Manager <a class="header-anchor" href="#⚡-bandwidth-manager" aria-label="Permalink to &quot;⚡ Bandwidth Manager&quot;">​</a></h2><p>Production-grade Docker container bandwidth management. Per-container speed limits, daily traffic quotas, kernel-level tc enforcement with modern TUI and webhook notifications.</p><p><a href="/pingless-studios-docs/bandwidth-manager/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/Bandwidth-flow-maintainer" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🛡️-protection-plus" tabindex="-1">🛡️ Protection Plus <a class="header-anchor" href="#🛡️-protection-plus" aria-label="Permalink to &quot;🛡️ Protection Plus&quot;">​</a></h2><p>Host-level abuse protection and antivirus for hosting providers. Catches miners, outbound DDoS, Tor exits and proxies, port scans, webshells and malware uploads, zip bombs and exploits on Pterodactyl/Docker/VPS nodes — with per-container network visibility, on-access YARA + hash-blocklist scanning, Discord/email/webhook alerts, and automatic enforcement (kill, suspend, quarantine).</p><p><a href="/pingless-studios-docs/protection/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/protection" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="⚡-mcu-hitter" tabindex="-1">⚡ mcu-hitter <a class="header-anchor" href="#⚡-mcu-hitter" aria-label="Permalink to &quot;⚡ mcu-hitter&quot;">​</a></h2><p>High-performance DDoS testing and benchmarking tool. Supports UDP flood, TCP SYN, ICMP, raw packet crafting with IP spoofing.</p><p><a href="https://github.com/AnAverageBeing/mcu-hitter" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🗄️-s3-database-storage-for-vps" tabindex="-1">🗄️ S3 Database Storage for VPS <a class="header-anchor" href="#🗄️-s3-database-storage-for-vps" aria-label="Permalink to &quot;🗄️ S3 Database Storage for VPS&quot;">​</a></h2><p>Automatic PostgreSQL and MySQL/MariaDB backups to any S3-compatible storage. Interactive setup, auto-discovery, systemd scheduling, retention, off-site + on-node copies, Discord alerts, and an interactive extractor.</p><p><a href="/pingless-studios-docs/s3-database-storage-for-vps/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/s3-database-storage-for-vps" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="⚡-penetration-v3" tabindex="-1">⚡ Penetration-v3 <a class="header-anchor" href="#⚡-penetration-v3" aria-label="Permalink to &quot;⚡ Penetration-v3&quot;">​</a></h2><p>Advanced traffic generation and packet crafting tool for authorized penetration testing. Supports 38 methods across UDP, TCP, ICMP, HTTP/S, DNS, NTP, SNMP, application-layer protocols, and IPv6 with an interactive TUI wizard and scriptable CLI mode.</p><p><a href="/pingless-studios-docs/pentest-v3/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/Penetration-v3" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🎮-bandwidth-monitor-for-pterodactyl" tabindex="-1">🎮 Bandwidth Monitor for Pterodactyl <a class="header-anchor" href="#🎮-bandwidth-monitor-for-pterodactyl" aria-label="Permalink to &quot;🎮 Bandwidth Monitor for Pterodactyl&quot;">​</a></h2><p>Per-server network monitoring and bandwidth control for Pterodactyl panels. A Blueprint panel extension plus a Go agent on each Wings node: RX/TX speed caps via tc, day/week/month quotas per direction, throttle/suspend/log-only exceed actions, per-node pairing tokens, hourly/daily rollups, usage predictions, and reports in a native AdminLTE admin UI.</p><p><a href="/pingless-studios-docs/pterodactyl-bandwidth-monitor/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="glacier-theme-for-pterodactyl" tabindex="-1">Glacier Theme for Pterodactyl <a class="header-anchor" href="#glacier-theme-for-pterodactyl" aria-label="Permalink to &quot;Glacier Theme for Pterodactyl&quot;">​</a></h2><p>A calm, Apple-grade sidebar theme for Pterodactyl Panel, built on Blueprint. Replaces the stock top navigation with a customizable sidebar in three docks, reskins every page in dark and light mode with full per-mode palettes, and adds a console zones editor, dashboard cover-image cards, a visual tab manager, Ctrl+K search, 16 pure-CSS background patterns, announcements, and per-user privacy mode — all configured from a live-preview admin hub, with zero core-file replacement and zero external assets.</p><p><a href="/pingless-studios-docs/glacier/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="apple-theme-for-pterodactyl-admin" tabindex="-1">Apple Theme for Pterodactyl Admin <a class="header-anchor" href="#apple-theme-for-pterodactyl-admin" aria-label="Permalink to &quot;Apple Theme for Pterodactyl Admin&quot;">​</a></h2><p>An iOS-grade matte glass theme for the Pterodactyl admin area, built on Blueprint. Frosted sidebar and floating top bar in Catppuccin Mocha and Latte with 12 accents, a runtime-harvested sidebar where every extension&#39;s links appear automatically, a global reskin of every AdminLTE component so extension pages adapt untouched, a bento dashboard with live stats and an inline-SVG signup sparkline, and a branded boot loader — Blueprint or standalone, with zero core-file replacement.</p><p><a href="/pingless-studios-docs/apple/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="🛡️-liteshield-xdp" tabindex="-1">🛡️ LiteShield-XDP <a class="header-anchor" href="#🛡️-liteshield-xdp" aria-label="Permalink to &quot;🛡️ LiteShield-XDP&quot;">​</a></h2><p>Free, minimal XDP (eBPF) firewall for Linux 5.15+. One XDP program, one Go binary, one YAML config — per-source-IP rate limits, auto-ban, live whitelist/blacklist, built-in status TUI, and Discord webhook alerts. No license server, no daemons, MIT-licensed.</p><p><a href="/pingless-studios-docs/liteshield-xdp/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/LiteShield-XDP" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🚀-nitrocord" tabindex="-1">🚀 NitroCord <a class="header-anchor" href="#🚀-nitrocord" aria-label="Permalink to &quot;🚀 NitroCord&quot;">​</a></h2><p>Velocity-compatible Minecraft proxy with built-in, license-gated attack prevention — kernel ipset firewall, TCP fingerprinting, anti-bot verification, anti-VPN/GeoIP, packet flood scoring, null-ping-proof MOTD caching, exploit filters, and an attack-mode engine that adapts the whole proxy under load. Drop-in replacement for Velocity: all plugins work unchanged.</p><p><a href="/pingless-studios-docs/nitrocord/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="firewall-plus-for-pterodactyl" tabindex="-1">Firewall-Plus for Pterodactyl <a class="header-anchor" href="#firewall-plus-for-pterodactyl" aria-label="Permalink to &quot;Firewall-Plus for Pterodactyl&quot;">​</a></h2><p>Production-grade per-container iptables firewall for Pterodactyl Panel (Blueprint or standalone addon) plus a Wings node daemon, with DDoS SMART detection and automatic mitigation. 13 rule types, ipset whitelist/blacklist, per-port or global scopes, game presets, queued atomic applies with snapshots and rollback, drift detection, an emergency operations page, and a full client UI with dashboards, charts, presets, AbuseIPDB, and owner Discord/email attack alerts.</p><p><a href="/pingless-studios-docs/firewall-plus/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/pterodactyl-firewall-plus" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="glacier-pack-for-pterodactyl" tabindex="-1">Glacier Pack for Pterodactyl <a class="header-anchor" href="#glacier-pack-for-pterodactyl" aria-label="Permalink to &quot;Glacier Pack for Pterodactyl&quot;">​</a></h2><p>A family of 24 standalone addons for Pterodactyl Panel v1.12.x plus the Glacier Pack hub — a single custom admin dashboard that hosts every addon&#39;s complete management UI in one Glacier-styled page. Includes a recycle bin, URL downloads, config editor, login activity, panel log viewer, node status and resource alerts, the full Minecraft suite (plugin/mod/modpack installers, version changer, player manager, player list, server properties), database manager, server importer, subdomain manager, staff requests, node analytics, S3 backups, and a permission manager for scoped staff roles. Addons inherit the Glacier theme&#39;s design tokens when it is installed and keep their own polished look when it is not.</p><p><a href="/pingless-studios-docs/glacier-pack/">Documentation →</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Contact →</a></p><h2 id="pterodactyl-revamp" tabindex="-1">Pterodactyl Revamp <a class="header-anchor" href="#pterodactyl-revamp" aria-label="Permalink to &quot;Pterodactyl Revamp&quot;">​</a></h2><p>Enterprise operations layer for Pterodactyl Panel 1.12.x–1.14.x, installable as a Blueprint extension or a standalone PanelFiles merge. Bulk server operations, multi-server creation, tagging, server templates, an allocation port picker, metrics and analytics dashboards, node/server health scoring, global search, and a full audit log — all from a dedicated <code>/admin/revamp</code> hub.</p><p><a href="/pingless-studios-docs/pterodactyl-revamp/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/pterodactyl-revamp" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="sentinel-for-pterodactyl" tabindex="-1">Sentinel for Pterodactyl <a class="header-anchor" href="#sentinel-for-pterodactyl" aria-label="Permalink to &quot;Sentinel for Pterodactyl&quot;">​</a></h2><p>Fleet-wide security monitoring and enforcement for Pterodactyl panels — a Laravel panel addon (the brain) plus a static Go agent on each Wings node (the sensor/enforcer). Twelve detectors catch cryptominers, port scans, outbound DDoS, zip bombs, privilege escalation, abuse tooling and malware; a graduated rules engine kills processes, quarantines files, pauses or stops containers, and suspends servers panel-side. Threat intel is shared across the fleet — a hash confirmed by enough nodes is blocked everywhere — and the whole config is edited once in the admin UI and pushed, versioned, to every node.</p><p><a href="/pingless-studios-docs/pterodactyl-sentinel/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/pterodactyl-sentinel" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="ask-access-for-pterodactyl" tabindex="-1">Ask Access for Pterodactyl <a class="header-anchor" href="#ask-access-for-pterodactyl" aria-label="Permalink to &quot;Ask Access for Pterodactyl&quot;">​</a></h2><p>Server access requests for Pterodactyl Panel, as a Blueprint addon or standalone extension. Users request access to a server by ID or to all of someone&#39;s servers by email; owners approve, deny, or revoke from a built-in account page with Read-only/Standard/Full permission presets, temporary auto-expiring grants, delegated access managers, user blocking, admin allowlist/blacklist policy, and a full audit trail.</p><p><a href="/pingless-studios-docs/ask-access/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/Ask-Access" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="trash-bin-pro-for-pterodactyl" tabindex="-1">Trash Bin Pro for Pterodactyl <a class="header-anchor" href="#trash-bin-pro-for-pterodactyl" aria-label="Permalink to &quot;Trash Bin Pro for Pterodactyl&quot;">​</a></h2><p>Recoverable file deletion for Pterodactyl Panel (Blueprint or standalone addon). Deleted files move to a hidden /.trash folder instead of vanishing — with per-server trash quotas, per-egg retention windows, an hourly fault-tolerant purge, collision-safe restores, a trashbinpro.access subuser permission, quota-aware delete flows in the file manager, activity logging, and a full admin panel for global settings, egg overrides and manual purges.</p><p><a href="/pingless-studios-docs/trash-bin-pro/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/pterodactyl-trash-bin-pro" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="blue-mod-installer-for-pterodactyl" tabindex="-1">Blue Mod Installer for Pterodactyl <a class="header-anchor" href="#blue-mod-installer-for-pterodactyl" aria-label="Permalink to &quot;Blue Mod Installer for Pterodactyl&quot;">​</a></h2><p>A mod installer for Minecraft servers with support for CurseForge &amp; Modrinth, built as a Blueprint extension. Adds a Mod Installer tab to every server&#39;s sidebar: search with loader/version filters, browse every version of a mod, and install in one click — the panel resolves the file through the provider API (your CurseForge key stays server-side) and Wings pulls it into <code>/mods</code>. Blueprint or standalone manual install.</p><p><a href="/pingless-studios-docs/blue-mod-installer/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/blue-mod-installer" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="blue-plugin-installer-for-pterodactyl" tabindex="-1">Blue Plugin Installer for Pterodactyl <a class="header-anchor" href="#blue-plugin-installer-for-pterodactyl" aria-label="Permalink to &quot;Blue Plugin Installer for Pterodactyl&quot;">​</a></h2><p>Browse, install, and manage Minecraft plugins from five providers — Modrinth, CurseForge, Hangar, SpigotMC, and Polymart — as a Blueprint extension. Adds a Plugin Installer tab to every server&#39;s sidebar with type/version filtering and a version browser; the panel downloads the chosen file server-side and uploads it into <code>/plugins</code> through Wings. Blueprint or standalone manual install.</p><p><a href="/pingless-studios-docs/blue-plugin-installer/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/blue-plugin-installer" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="blue-server-properties-editor-for-pterodactyl" tabindex="-1">Blue Server Properties Editor for Pterodactyl <a class="header-anchor" href="#blue-server-properties-editor-for-pterodactyl" aria-label="Permalink to &quot;Blue Server Properties Editor for Pterodactyl&quot;">​</a></h2><p>A modern <code>server.properties</code> editor for Minecraft servers (nest ID 1), built as a Blueprint extension with an additional genuinely Blueprint-free variant. Every key rendered with the right control — toggles for booleans, dropdowns for difficulty/gamemode — in a 3-column grid with category filtering, read and written live through Wings with comments preserved. Customizable sidebar label from the admin page.</p><p><a href="/pingless-studios-docs/blue-server-properties/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/blue-server-properties" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="🛡️-panel-firewall-for-pterodactyl" tabindex="-1">🛡️ Panel Firewall for Pterodactyl <a class="header-anchor" href="#🛡️-panel-firewall-for-pterodactyl" aria-label="Permalink to &quot;🛡️ Panel Firewall for Pterodactyl&quot;">​</a></h2><p>Host-level firewall and DDoS mitigation for the Pterodactyl Panel host itself. An admin-only panel UI drives a privileged, HMAC-authenticated Node.js daemon: L3/L4 packet hygiene and per-IP rate limits with 5 presets, EWMA-based SMART auto-mitigation, L7 HTTP-flood detection from web-server access logs, whitelist/blacklist ipsets — all applied transactionally with checkpoints and 60-second auto-rollback.</p><p><a href="/pingless-studios-docs/panel-firewall/">Documentation →</a> · <a href="https://github.com/AnAverageBeing/pterodactyl-panel-firewall" target="_blank" rel="noreferrer">GitHub →</a></p><h2 id="📦-more-projects" tabindex="-1">📦 More Projects <a class="header-anchor" href="#📦-more-projects" aria-label="Permalink to &quot;📦 More Projects&quot;">​</a></h2><p>Follow <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">PingLess Studios on GitHub</a> for new projects and updates.</p>',66)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
